import java.util.OptionalInt;

public final class Solution {
    private Solution() {
    }

    public static OptionalInt averageValidIntegers(String[] tokens) {
        if (tokens == null) {
            return OptionalInt.empty();
        }

        int sum = 0;
        int count = 0;
        for (String token : tokens) {
            if (token == null) {
                continue;
            }
            try {
                int value = Integer.parseInt(token.trim());
                sum += value;
                count++;
            } catch (NumberFormatException ignored) {
                // Malformed and out-of-range tokens are excluded.
            }
        }

        return count == 0
                ? OptionalInt.empty()
                : OptionalInt.of(sum / count);
    }
}

