import java.util.Arrays;
import java.util.OptionalInt;

public class SolutionTest {
    public static void main(String[] args) {
        assertEmpty(Solution.averageValidIntegers(null));
        assertEmpty(Solution.averageValidIntegers(new String[0]));
        assertEmpty(Solution.averageValidIntegers(new String[]{null, "", "   ", "1.5", "12x", "2147483648"}));

        assertValue(20, Solution.averageValidIntegers(new String[]{"10", " 20 ", "\t30\n"}));
        assertValue(0, Solution.averageValidIntegers(new String[]{"-2", "1"}));
        assertValue(-1, Solution.averageValidIntegers(new String[]{"-2", "-1"}));
        assertValue(0, Solution.averageValidIntegers(new String[]{"+7", "-7", "bad", null}));
        assertValue(Integer.MAX_VALUE, Solution.averageValidIntegers(new String[]{"2147483647", "2147483647"}));
        assertValue(Integer.MIN_VALUE, Solution.averageValidIntegers(new String[]{"-2147483648", "-2147483648"}));
        assertValue(0, Solution.averageValidIntegers(new String[]{"2147483647", "-2147483648"}));

        String[] input = {" 1 ", "invalid", null, "3"};
        String[] snapshot = input.clone();
        assertValue(2, Solution.averageValidIntegers(input));
        if (!Arrays.equals(snapshot, input)) throw new AssertionError("input array was modified");
        for (int i = 0; i < input.length; i++) {
            if (input[i] != snapshot[i]) throw new AssertionError("input element reference was replaced");
        }
    }

    private static void assertEmpty(OptionalInt value) {
        if (value == null || value.isPresent()) throw new AssertionError("expected OptionalInt.empty");
    }

    private static void assertValue(int expected, OptionalInt actual) {
        if (actual == null || !actual.isPresent() || actual.getAsInt() != expected) {
            throw new AssertionError("expected " + expected + " but got " + actual);
        }
    }
}

